-- Demo products (same as the website's built-in list). Run AFTER schema.sql.
-- Safe to re-run: it updates existing rows.
on conflict (id) do update set name=excluded.name, brand=excluded.brand, cat=excluded.cat, price=excluded.price, mrp=excluded.mrp, rating=excluded.rating, reviews=excluded.reviews, emoji=excluded.emoji, image=excluded.image, description=excluded.description, stock=excluded.stock, prescription=excluded.prescription, tags=excluded.tags, popular=excluded.popular;
